async(page)=>{
 const base='http://127.0.0.1:5173/',checks=[],metrics=[],browser=page.context().browser(),check=(v,m)=>{if(!v)throw Error(m);checks.push(m)},cloud=/tcloudbasegateway\.com|tcb-api\.tencentcloudapi\.com/,main=url=>/\/src\/main\.tsx$|\/assets\/index-[^/]+\.js$/.test(new URL(url).pathname)
 for(const mobile of [false,true]){const context=await browser.newContext({viewport:mobile?{width:390,height:844}:{width:1440,height:900},...(mobile?{isMobile:true,hasTouch:true,userAgent:'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36 MicroMessenger/8.0.50'}:{})});try{const p=await context.newPage(),calls=[],sdk=[],errors=[];p.on('request',r=>{if(cloud.test(r.url()))calls.push(r.url());if(/index\.esm-|@cloudbase.*js-sdk/.test(r.url()))sdk.push(r.url())});p.on('pageerror',e=>errors.push(e.message));await p.route(cloud,r=>r.abort());const t=Date.now();await p.goto(base);await p.getByRole('heading',{name:'注册网页账号',exact:true}).waitFor({timeout:20000});metrics.push({mobile,ms:Date.now()-t,url:p.url()});check(p.url()===base,'正式根网址直接进入注册 '+mobile);check(!calls.length&&!sdk.length,'无会话首屏不依赖云端或认证SDK '+mobile);check(!errors.length,'首次入口无脚本异常 '+mobile);await p.getByRole('button',{name:'已有账号，去登录',exact:true}).click();check(await p.getByRole('heading',{name:'登录小食云记',exact:true}).isVisible(),'账号入口可切换 '+mobile)}finally{await context.close()}}
 const context=await browser.newContext({viewport:{width:390,height:844}});try{const p=await context.newPage(),block=async r=>r.abort();await p.route(main,block);await p.goto(base);await p.getByRole('button',{name:'重新加载',exact:true}).waitFor({timeout:20000});check((await p.locator('body').innerText()).includes('页面资源加载较慢'),'主脚本失败有静态提示');await p.unroute(main,block);await p.getByRole('button',{name:'重新加载',exact:true}).click();await p.getByRole('heading',{name:'注册网页账号',exact:true}).waitFor({timeout:20000});check(new URL(p.url()).searchParams.has('_reload'),'失败后重试避开旧HTML缓存');check(true,'脚本恢复后可进入真实注册页');await p.route(main,async r=>{await new Promise(resolve=>setTimeout(resolve,1500));await r.continue()});await p.goto(base);await p.getByRole('heading',{name:'注册网页账号',exact:true}).waitFor({timeout:20000});check(true,'主脚本慢请求可恢复进入')}finally{await context.close()}
 if(base.startsWith('https://bboy-lan.github.io')){const context=await browser.newContext();try{const p=await context.newPage(),oldHtml=await (await p.request.get('http://127.0.0.1:5173/.release/previous-pages.html')).text(),assets=[],failures=[];await p.route(base,r=>r.fulfill({status:200,contentType:'text/html',body:oldHtml}));p.on('response',r=>{if(/\/assets\/[^/]+\.(js|css)$/.test(new URL(r.url()).pathname)){assets.push({url:r.url(),status:r.status()});if(!r.ok())failures.push(r.url())}});await p.goto(base);await p.getByRole('heading',{name:'注册网页账号',exact:true}).waitFor({timeout:20000});check(true,'旧HTML缓存仍能加载旧主脚本和CSS');await p.route(cloud,r=>r.abort());await p.getByRole('button',{name:'已有账号，去登录',exact:true}).click();await p.getByRole('textbox',{name:'登录账号',exact:true}).fill('cache-compat-no-real-account');await p.getByLabel('登录密码',{exact:true}).fill('CompatibilityCheck123!');await p.getByRole('button',{name:'登录',exact:true}).click();await p.waitForFunction(()=>performance.getEntriesByType('resource').some(r=>/index\.esm-/.test(r.name)));await p.waitForTimeout(500);check(assets.some(a=>/index\.esm-/.test(a.url)&&a.status===200)&&!failures.length,'旧页面延迟认证SDK和依赖继续返回200');metrics.push({oldHtmlAssets:assets})}finally{await context.close()}}
 return {base,checks,metrics,realDevice:false}
}
